{"acl": ["=X/postgres", "postgres=X/postgres", "anon=X/postgres", "authenticated=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path="""], "definition": "CREATE OR REPLACE FUNCTION public.log_review_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  audit_event text;
  audit_review_type text;
  audit_review_id uuid;
  audit_reviewer_id uuid;
  audit_target_id text;
  audit_question_id text;
  audit_source_version uuid;
begin
  audit_review_type :=
    case TG_TABLE_NAME
      when 'question_reviews' then 'question'
      when 'answer_reviews' then 'answer'
      else null
    end;

  if audit_review_type is null then
    raise exception 'UNSUPPORTED_REVIEW_AUDIT_TABLE';
  end if;

  if TG_OP = 'INSERT' then
    audit_event := 'created';

    audit_review_id := new.id;
    audit_reviewer_id := new.reviewer_id;

    audit_target_id :=
      case
        when audit_review_type = 'question'
          then new.question_id
        else (pg_catalog.to_jsonb(NEW) ->> 'answer_id')
      end;

    audit_question_id := new.question_id;
    audit_source_version := new.source_version;

    insert into public.review_audit_log (
      review_type,
      review_id,
      reviewer_id,
      target_id,
      question_id,
      source_version,
      event_type,
      before_data,
      after_data
    )
    values (
      audit_review_type,
      audit_review_id,
      audit_reviewer_id,
      audit_target_id,
      audit_question_id,
      audit_source_version,
      audit_event,
      null,
      to_jsonb(new)
    );

    return new;
  end if;


  if TG_OP = 'UPDATE' then
    if old.is_active = true
      and new.is_active = false
      and new.inactive_reason = 'deleted'
    then
      audit_event := 'deleted';

    elsif old.is_active = true
      and new.is_active = false
      and new.inactive_reason = 'source_updated'
    then
      audit_event := 'source_updated';

    elsif old.is_active = false
      and new.is_active = true
    then
      audit_event := 'reactivated';

    else
      audit_event := 'edited';
    end if;

    audit_review_id := new.id;
    audit_reviewer_id := new.reviewer_id;

    audit_target_id :=
      case
        when audit_review_type = 'question'
          then new.question_id
        else (pg_catalog.to_jsonb(NEW) ->> 'answer_id')
      end;

    audit_question_id := new.question_id;
    audit_source_version := new.source_version;

    insert into public.review_audit_log (
      review_type,
      review_id,
      reviewer_id,
      target_id,
      question_id,
      source_version,
      event_type,
      before_data,
      after_data
    )
    values (
      audit_review_type,
      audit_review_id,
      audit_reviewer_id,
      audit_target_id,
      audit_question_id,
      audit_source_version,
      audit_event,
      to_jsonb(old),
      to_jsonb(new)
    );

    return new;
  end if;


  if TG_OP = 'DELETE' then
    audit_event := 'hard_deleted';

    audit_review_id := old.id;
    audit_reviewer_id := old.reviewer_id;

    audit_target_id :=
      case
        when audit_review_type = 'question'
          then old.question_id
        else (pg_catalog.to_jsonb(OLD) ->> 'answer_id')
      end;

    audit_question_id := old.question_id;
    audit_source_version := old.source_version;

    insert into public.review_audit_log (
      review_type,
      review_id,
      reviewer_id,
      target_id,
      question_id,
      source_version,
      event_type,
      before_data,
      after_data
    )
    values (
      audit_review_type,
      audit_review_id,
      audit_reviewer_id,
      audit_target_id,
      audit_question_id,
      audit_source_version,
      audit_event,
      to_jsonb(old),
      null
    );

    return old;
  end if;

  return null;
end;
$function$
